package com.xdownload.mobile;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;
/** No automatic background service launch at boot. User chooses recovery after notification. */
public final class RecoveryReceiver extends BroadcastReceiver{
 static final int NOTICE=90435;static final String CHANNEL="xdownload.recovery";
 @Override public void onReceive(Context c,Intent intent){if(intent==null||!Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction()))return;try{ScheduleService.arm(c);if(!Store.settings(c).getBoolean("recovery_notice",true))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;int count=0;for(Store.Job j:Store.get(c).list())if(j.recoverable())count++;if(count==0)return;NotificationManager nm=c.getSystemService(NotificationManager.class);if(nm==null||!nm.areNotificationsEnabled())return;boolean en=Store.settings(c).getBoolean("english",false);nm.createNotificationChannel(new NotificationChannel(CHANNEL,en?"Download recovery":"استعادة التحميلات",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,NOTICE,new Intent(c,MainActivity.class).putExtra("recover_jobs",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);nm.notify(NOTICE,new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle(en?"Recover interrupted downloads":"استعادة التحميلات المنقطعة").setContentText(count+" • "+(en?"Tap to review and resume":"اضغط للمراجعة والاستكمال")).setContentIntent(open).setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).build());}catch(RuntimeException ignored){}}
}